package pe.com.dentalamericana.copilot;
import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import pe.com.dentalamericana.copilot.dto.CopilotDtos.*;import pe.com.dentalamericana.security.AuthenticatedUser;import java.util.List;
@RestController@RequestMapping("/api/v1/copilot")public class CopilotController{private final CopilotService service;public CopilotController(CopilotService service){this.service=service;}@GetMapping("/drafts")@PreAuthorize("hasAuthority('IA_LEER')")public List<DraftResponse>list(@RequestParam Long encounterId){return service.list(encounterId);}@PostMapping("/drafts")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAuthority('IA_ESCRIBIR')")public DraftResponse generate(@Valid@RequestBody GenerateDraftRequest r,@AuthenticationPrincipal AuthenticatedUser a,HttpServletRequest h){return service.generate(r,a,h);}@PatchMapping("/drafts/{id}/approve")@PreAuthorize("hasAuthority('IA_APROBAR')")public DraftResponse approve(@PathVariable Long id,@Valid@RequestBody ReviewDraftRequest r,@AuthenticationPrincipal AuthenticatedUser a,HttpServletRequest h){return service.approve(id,r,a,h);}@PatchMapping("/drafts/{id}/reject")@PreAuthorize("hasAuthority('IA_APROBAR')")public DraftResponse reject(@PathVariable Long id,@Valid@RequestBody ReviewDraftRequest r,@AuthenticationPrincipal AuthenticatedUser a,HttpServletRequest h){return service.reject(id,r,a,h);}}
